type Task = { done: boolean };

export function completedCount(tasks: Task[]): number {
  return tasks.filter((task) => task.done).length;
}

export function groupBy<T, K extends keyof T>(items: T[], key: K): Map<T[K], T[]> {
  const map = new Map<T[K], T[]>();
  for (const item of items) {
    const k = item[key];
    const group = map.get(k) ?? [];
    group.push(item);
    map.set(k, group);
  }
  return map;
}

export type DeepPartial<T> = T extends object
  ? { [P in keyof T]?: DeepPartial<T[P]> }
  : T;

export function assertDefined<T>(value: T, message = 'value is nullish'): asserts value is NonNullable<T> {
  if (value == null) throw new Error(message);
}

export function debounceAsync<T extends unknown[]>(
  fn: (...args: T) => Promise<void>,
  ms: number
): (...args: T) => void {
  let timer: ReturnType<typeof setTimeout>;
  return (...args: T) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

type RequestState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: string };

export function getMessage<T>(state: RequestState<T>): string {
  switch (state.status) {
    case 'idle':    return 'Waiting to start.';
    case 'loading': return 'Loading…';
    case 'success': return 'Done.';
    case 'error':   return `Error: ${state.error}`;
  }
}

export function pick<T extends object, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  return Object.fromEntries(keys.map(k => [k, obj[k]])) as Pick<T, K>;
}

export interface Paginated<T> {
  data: T[];
  page: number;
  totalPages: number;
}

export function hasNextPage<T>(response: Paginated<T>): boolean {
  return response.page < response.totalPages;
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

type Listener<T> = (payload: T) => void;

export class TypedEmitter<Events extends Record<string, unknown>> {
  private listeners = new Map<keyof Events, Set<Listener<unknown>>>();

  on<K extends keyof Events>(event: K, fn: Listener<Events[K]>): this {
    (this.listeners.get(event) ?? this.listeners.set(event, new Set()).get(event)!)
      .add(fn as Listener<unknown>);
    return this;
  }

  emit<K extends keyof Events>(event: K, payload: Events[K]): void {
    this.listeners.get(event)?.forEach(fn => fn(payload));
  }
}

export type KeysOfType<T, V> = {
  [K in keyof T]: T[K] extends V ? K : never;
}[keyof T];

export function safeJsonParse<T>(raw: string): T | null {
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

export function intersection<T>(a: T[], b: T[]): T[] {
  const setB = new Set(b);
  return [...new Set(a)].filter(x => setB.has(x));
}

type RGB = readonly [r: number, g: number, b: number];

export function rgbToCss([r, g, b]: RGB): string {
  return `rgb(${r}, ${g}, ${b})`;
}

export function flattenRecord(record: Record<string, string[]>): string[] {
  return Object.values(record).flat();
}

export class Cache<K, V> {
  private store = new Map<K, V>();

  get(key: K): V | undefined { return this.store.get(key); }
  set(key: K, value: V): this { this.store.set(key, value); return this; }
  has(key: K): boolean       { return this.store.has(key); }
  size(): number             { return this.store.size; }
}

export function toIdMap<T extends { id: string | number }>(items: T[]): Map<T['id'], T> {
  return new Map(items.map(item => [item.id, item]));
}

export function sortByDesc<T>(items: T[], key: keyof T): T[] {
  return [...items].sort((a, b) => {
    const av = a[key] as number;
    const bv = b[key] as number;
    return bv - av;
  });
}

declare const __brand: unique symbol;
type Brand<T, B> = T & { [__brand]: B };

export type Email = Brand<string, 'Email'>;

export function asEmail(value: string): Email {
  if (!value.includes('@')) throw new Error('invalid email');
  return value as Email;
}

export function deepMerge<T extends Record<string, unknown>>(base: T, override: Partial<T>): T {
  const result: Record<string, unknown> = { ...base };
  for (const key of Object.keys(override) as (keyof T)[]) {
    const ov = override[key];
    const bv = base[key];
    if (ov && typeof ov === 'object' && !Array.isArray(ov)
     && bv && typeof bv === 'object' && !Array.isArray(bv)) {
      result[key as string] = deepMerge(
        bv as Record<string, unknown>,
        ov as Record<string, unknown>
      );
    } else if (ov !== undefined) {
      result[key as string] = ov;
    }
  }
  return result as T;
}
